mapper.select:
select id, company_id, userid, schedulingtime, timeid, is_locked,
       create_by, create_date, update_by, update_date, del_flag
from scheduling_data sd

    company_id =#{companyid}

        and userid =#{userid}


        and schedulingtime >= #{stratime}


        and schedulingtime <= #{endtime}


order by schedulingtime

select a.id,a.patient_id, p.name,sdib.name gendername,p.age,a.subscribe_date ,su.name ysname,sue.office ksname,sdia.name sourcename, sdi.name statusname,a.remarks ,a.create_date,DATE_FORMAT(a.subscribe_date,'%H') houser from registration a left join patient p on a.patient_id =p.id and a.company_id =p.company_id left join sys_dict_item sdi on a.status=sdi.value and sdi.del_flag ='0' left join sys_dict_item sdia on a.source=sdia.value and sdia.del_flag ='0' left join sys_dict_item sdib on p.gender=sdib.value and sdib.del_flag ='0' left join sys_user su on a.company_id =su.company_id and a.department_id =su.department_id and a.doctor_id =su.id left join sys_user_ext sue on su.company_id =sue.company_id and su.id =sue.user_id
a.del_flag='0' and a.overlook='0' and a.company_id =#{companyid} and a.subscribe_date is not null
and a.doctor_id =#{userid}
and a.department_id=#{ksid}
and a.status =#{status}
and p.name like concat('%',#{patientname},'%')
and a.subscribe_date >=#{datestra}
and a.subscribe_date <= #{dateend}
order by a.subscribe_date

mapper.update:
update scheduling_data set del_flag='1',update_by =#{updateBy},update_date =#{updateDate}
where userid=#{userid} and schedulingtime =#{schedulingtime}
and company_id =#{companyid}
and del_flag ='0' and is_locked ='0'
